// =====================================================================
// M1 · maestro MODBus — "On Message" del function node
// docs/diagramas/flujo-maestro.mmd, bloques [DF-2.3] (comandos pendientes)
// y [DF-2.17] (reconfiguracion en vivo, I-04)
// ---------------------------------------------------------------------
// Descripcion: atiende los mensajes que llegan al maestro, segun msg.topic:
//   bytes                bloque recibido por serial in (lo envia M2)
//   puerto-confirmado    respuesta de serial control (lo envia M3)
//   escribir             {nombre, valor} desde el Dashboard u OPC UA (F4)
//   reconfigurar         configuracion completa (la arma D1 desde el Dashboard)
//   probar               {fc, direccion, cantidad}: una peticion, trama cruda de ida y vuelta
//   trama                "ID PDU" en hexadecimal: el maestro agrega el CRC propio
//   descubrir            opciones del asistente de descubrimiento
//   explorar             {fc, desde, hasta}: que direcciones existen
//   cancelar             corta el descubrimiento o la exploracion
//   reiniciar-contadores pone en cero OK / CRC_ERROR / TIMEOUT / EXCEPTION
//   pedir-config         reenvia la configuracion vigente al panel
// Las respuestas salen por la salida 5 con el topic indicado en cada caso.
// =====================================================================
const pdci = global.get('pdci');
const maestro = context.get('maestro');
if (!maestro) return null;

const responder = (topic, payload, extra) =>
    node.send([null, null, null, null, Object.assign({ topic, payload }, extra || {})]);
const fallar = (topic, error) => responder(topic, { ok: false, error: String(error && error.message || error) });

switch (msg.topic) {
    case 'bytes':
        maestro.recibir(msg.payload);
        return null;

    case 'puerto-confirmado':
        context.get('confirmarPuerto')(msg.payload);
        return null;

    case 'escribir': {
        const { nombre, valor } = msg.payload || {};
        maestro.escribir(nombre, valor)
            .then((r) => responder('escritura', Object.assign({ nombre, valor }, r), { _origen: msg._origen }))
            .catch((e) => fallar('escritura', e));
        return null;
    }

    case 'reconfigurar':                                         // [DF-2.17]
        maestro.reconfigurar(msg.payload).then((r) => {
            if (r.ok) {
                try {
                    pdci.configuracion.guardar(pdci.rutas.config, r.config);   // sobrevive al reinicio
                } catch (e) {
                    node.warn(`configuracion aplicada pero no guardada: ${e.message}`);
                    r.errores = (r.errores || []).concat(`no se pudo guardar: ${e.message}`);
                }
                responder('config', r.config, { origen: 'usuario' });
            }
            responder('reconfiguracion', { ok: r.ok, errores: r.errores });
        }).catch((e) => fallar('reconfiguracion', e));
        return null;

    case 'probar':
        maestro.probar(msg.payload || {}).then((r) => responder('prueba', r)).catch((e) => fallar('prueba', e));
        return null;

    case 'trama':
        maestro.tramaManual(String(msg.payload || '')).then((r) => responder('trama-manual', r))
            .catch((e) => fallar('trama-manual', e));
        return null;

    case 'descubrir':
        maestro.descubrir(msg.payload || {}, (p) => responder('progreso', p))
            .then((r) => responder('descubrimiento', r)).catch((e) => fallar('descubrimiento', e));
        return null;

    case 'explorar':
        maestro.explorar(msg.payload || {}).then((r) => responder('exploracion', r))
            .catch((e) => fallar('exploracion', e));
        return null;

    case 'cancelar':
        maestro.cancelar();
        return null;

    case 'reiniciar-contadores':
        maestro.reiniciarContadores();
        return null;

    case 'pedir-config':
        responder('config', maestro.config);
        return null;

    default:
        node.warn(`comando desconocido: ${msg.topic}`);
        return null;
}

initialize:
// =====================================================================
// M1 · maestro MODBus — "On Start" del function node
// docs/diagramas/flujo-maestro.mmd, bloque [DF-2.1] (inicio)
// ---------------------------------------------------------------------
// Descripcion: carga la configuracion persistida (o la de fabrica), crea el
//   maestro (lib/maestro.js) con un transporte compuesto -puerto serie de
//   node-red-node-serialport o TCP de desarrollo- y lo arranca.
//   El protocolo NO lo hace ningun nodo de la paleta: lo hace lib/modbus.js (I-01).
// Salidas: [1] serial out      Buffer con la trama a transmitir
//          [2] serial control  {serialport, serialbaud, databits, parity, stopbits, enabled}
//          [3] estado          instantanea del maestro (max. 2 por segundo) y eventos
//          [4] valores         una variable que cambio: topic = nombre, payload = valor
//          [5] respuestas      resultado de cada comando del panel (topic = tipo)
// Firma de la biblioteca (consigna: "parametros con tipo"):
//   new MaestroModbus({config: object, transporte: {enviar(Buffer): void,
//       reconfigurar(puerto: object): Promise<void>}}) : MaestroModbus
// =====================================================================
const pdci = global.get('pdci');
const { configuracion, MaestroModbus, transportes } = pdci;

const carga = configuracion.cargar(pdci.rutas.config);
carga.avisos.forEach((aviso) => node.warn(aviso));
const config = carga.config;

// --- Adaptador del puerto serie de Node-RED ------------------------------
// serial control responde ANTES de que el puerto termine de reabrir (changePort
// cierra y la reapertura es asincrona): la espera de asentamiento la hace el
// maestro con config.puerto.esperaReconfiguracionMs.
let confirmarPuerto = null;
const serie = {
    enviar: (trama) => node.send([{ payload: trama }, null, null, null, null]),
    reconfigurar: (puerto) => new Promise((resolver) => {
        confirmarPuerto = resolver;
        node.send([null, { payload: Object.assign(configuracion.paraSerialControl(puerto), { enabled: true }) },
            null, null, null]);
        // Si serial control no confirma (puerto inexistente), se sigue: el maestro contara TIMEOUT.
        setTimeout(() => { if (confirmarPuerto === resolver) { confirmarPuerto = null; resolver(); } }, 2000);
    }),
    deshabilitar: () => node.send([null, { payload: { enabled: false } }, null, null, null]),
};
context.set('confirmarPuerto', (estadoPuerto) => {
    if (confirmarPuerto) { const r = confirmarPuerto; confirmarPuerto = null; r(estadoPuerto); }
});

const transporte = new transportes.TransporteCompuesto(serie);
const maestro = new MaestroModbus({ config, transporte });
transporte.on('datos', (bloque) => maestro.recibir(bloque));
transporte.on('evento', (e) => pdci.historial.agregar(Object.assign({ capa: 'MODBUS' }, e)));

// Contadores persistidos (contexto "archivo"): sobreviven a un reinicio.
maestro.restaurarContadores(global.get('pdci_contadores', 'archivo'));

// --- Eventos del maestro ---------------------------------------------------
let ultimoEstado = null;
maestro.on('estado', (s) => {
    ultimoEstado = s;
    global.set('pdci_modbus', s);
    pdci.capas.actualizar('MODBUS', { estado: s.estado, contadores: {
        OK: s.contadores.OK, CRC_ERROR: s.contadores.CRC_ERROR, TIMEOUT: s.contadores.TIMEOUT,
        EXCEPTION: s.contadores.EXCEPTION }, detalle: { ultimaTx: s.ultimaTx, ultimaRx: s.ultimaRx,
        latenciaMs: s.latenciaMs, esclavo: s.esclavo, puerto: s.puerto, ...s.contadores.detalle } });
});
maestro.on('valor', (v) => node.send([null, null, null,
    { topic: v.nombre, payload: v.valor, calidad: v.calidad, ts: v.ts }, null]));
maestro.on('evento', (e) => {
    pdci.historial.agregar(e);
    node.status({ fill: e.nivel === 'info' ? 'green' : 'yellow', shape: 'dot', text: e.texto.slice(0, 60) });
});

// Estado hacia el panel y OPC UA a 2 por segundo como maximo: el maestro emite uno por
// peticion (16/s con 4 variables cada 250 ms) y no hace falta redibujar tanto.
const intervalo = setInterval(() => {
    if (ultimoEstado) node.send([null, null, { topic: 'estado', payload: ultimoEstado }, null, null]);
    ultimoEstado = null;
}, 500);

context.set('maestro', maestro);
context.set('transporte', transporte);
context.set('intervalo', intervalo);

// Arranque diferido: los nodos serie tienen que estar levantados antes de reconfigurarlos.
setTimeout(() => {
    transporte.reconfigurar(config.puerto).then(() => {
        maestro.iniciar();
        node.send([null, null, null, null, { topic: 'config', payload: config, origen: carga.origen }]);
        node.status({ fill: 'green', shape: 'dot', text: `sondeando: ${maestro.instantanea().puerto}` });
    });
}, 1000);
node.status({ fill: 'yellow', shape: 'ring', text: `iniciando (${carga.origen})` });

finalize:
// =====================================================================
// M1 · maestro MODBus — "On Stop" del function node
// ---------------------------------------------------------------------
// Descripcion: detiene el sondeo, libera temporizadores y el socket TCP de
//   desarrollo. Sin esto, cada Deploy dejaria un maestro viejo sondeando en
//   paralelo con el nuevo: dos maestros en un bus MODBus (leccion I-04 de la T2,
//   "cliente zombi").
// =====================================================================
const maestro = context.get('maestro');
if (maestro) maestro.detener();
const transporte = context.get('transporte');
if (transporte) transporte.destruir();
clearInterval(context.get('intervalo'));
// Contadores al archivo antes de salir.
const s = global.get('pdci_modbus');
if (s) global.set('pdci_contadores', s.contadores, 'archivo');

func:
// =====================================================================
// M2 · bytes recibidos — [DF-2.8]
// ---------------------------------------------------------------------
// Descripcion: marca cada bloque de serial in (modo binario, separacion
//   "interbyte" de 2 ms) como topic "bytes" y lo pasa a M1. La separacion
//   de 2 ms solo agrupa bytes: la delimitacion real de la respuesta la hace
//   el maestro por LONGITUD ESPERADA (ADR-012), porque Node-RED no puede
//   medir el silencio t3,5 con precision (docs/spike-nodered-opcua.md §3).
// =====================================================================
if (!Buffer.isBuffer(msg.payload)) return null;   // configurado en binario: llega un Buffer
msg.topic = 'bytes';
return msg;

// =====================================================================
// M3 · puerto reconfigurado — [DF-2.17]
// ---------------------------------------------------------------------
// Descripcion: serial control responde con la configuracion vigente del
//   puerto despues de cada cambio. Se reenvia a M1 como "puerto-confirmado"
//   para que el maestro continue la reconfiguracion o el descubrimiento.
// =====================================================================
msg.topic = 'puerto-confirmado';
node.status({ fill: msg.payload.enabled === false ? 'grey' : 'green', shape: 'dot',
    text: msg.payload.enabled === false ? 'puerto serie deshabilitado (TCP)'
        : `${msg.payload.serialport} ${msg.payload.serialbaud} ${msg.payload.databits}${String(msg.payload.parity)[0].toUpperCase()}${msg.payload.stopbits}` });
return msg;

// =====================================================================
// M4 · persistir contadores — I-05
// ---------------------------------------------------------------------
// Descripcion: cada 10 s copia los contadores MODBus al contexto "archivo"
//   (localfilesystem, settings.js), para que OK / CRC_ERROR / TIMEOUT /
//   EXCEPTION sobrevivan a un reinicio de Node-RED. M1 los restaura al arrancar.
// =====================================================================
const s = global.get('pdci_modbus');
if (s) global.set('pdci_contadores', s.contadores, 'archivo');
return null;
